(function(){
 const DATA=window.SRDM_ZERO_MANDAYS_DATA;
 const MONTHS=['April','May','June','July','August','September'];

 function norm(v){return String(v||'').replace(/[\u200B-\u200D\uFEFF]/g,'').replace(/\s+/g,' ').trim().toUpperCase()}
 function txt(v){return String(v||'').trim()}

 function navHost(){
   const candidates=[...document.querySelectorAll('button')];
   const ref=candidates.find(b=>/Mandays Generation/i.test(b.textContent||''));
   return ref?ref.parentElement:null;
 }

 function ensureButton(){
   if(document.getElementById('srdmZeroBtn'))return;
   const host=navHost(); if(!host)return;
   const b=document.createElement('button');
   b.type='button'; b.id='srdmZeroBtn'; b.textContent='Zero Mandays Generation';
   b.className=host.querySelector('button')?.className||'';
   b.addEventListener('click',renderZeroTab);
   host.appendChild(b);
 }

 function opt(id,vals,label){
   const s=document.getElementById(id);if(!s)return;
   const cur=s.value;
   s.innerHTML=`<option value="ALL">${label}</option>`+vals.map(v=>`<option value="${v}">${v}</option>`).join('');
   s.value=[...s.options].some(o=>o.value===cur)?cur:'ALL';
 }

 function getF(){
   return {
     d:document.getElementById('zDistrict')?.value||'ALL',
     j:document.getElementById('zJanpad')?.value||'ALL',
     e:document.getElementById('zEngineer')?.value||'ALL',
     c:document.getElementById('zCluster')?.value||'ALL',
     g:document.getElementById('zGP')?.value||'ALL',
     m:document.getElementById('zMonth')?.value||'August'
   }
 }

 function cascade(){
   const f=getF();
   opt('zDistrict',[...new Set(DATA.map(r=>r.district))].sort(),'सभी District');
   opt('zJanpad',[...new Set(DATA.filter(r=>f.d==='ALL'||r.district===f.d).map(r=>r.janpad))].sort(),'सभी Janpad');
   opt('zEngineer',[...new Set(DATA.filter(r=>(f.d==='ALL'||r.district===f.d)&&(f.j==='ALL'||r.janpad===f.j)).map(r=>r.engineer))].sort((a,b)=>String(a).localeCompare(String(b),'hi')),'सभी Sub Engineer');
   opt('zCluster',[...new Set(DATA.filter(r=>(f.d==='ALL'||r.district===f.d)&&(f.j==='ALL'||r.janpad===f.j)&&(f.e==='ALL'||r.engineer===f.e)).map(r=>r.cluster))].sort(),'सभी Cluster');
   opt('zGP',[...new Set(DATA.filter(r=>(f.d==='ALL'||r.district===f.d)&&(f.j==='ALL'||r.janpad===f.j)&&(f.e==='ALL'||r.engineer===f.e)&&(f.c==='ALL'||r.cluster===f.c)).map(r=>r.gp))].sort(),'सभी GP');
 }

 function filtered(){
   const f=getF();
   return DATA.filter(r=>
     (f.d==='ALL'||r.district===f.d)&&
     (f.j==='ALL'||r.janpad===f.j)&&
     (f.e==='ALL'||r.engineer===f.e)&&
     (f.c==='ALL'||r.cluster===f.c)&&
     (f.g==='ALL'||r.gp===f.g)&&
     Number(r[f.m]||0)===0
   );
 }

 function renderRows(){
   const f=getF(),d=filtered();
   const tbody=document.querySelector('#reportTable tbody');
   if(!tbody)return;
   tbody.innerHTML=d.map((r,i)=>`<tr>
     <td>${i+1}</td><td>${r.district}</td><td>${r.janpad}</td><td>${r.engineer}</td><td>${r.cluster}</td><td>${r.gp}</td><td>${f.m}</td><td><b>0</b></td>
   </tr>`).join('')+
   `<tr class="total-row"><td colspan="6">TOTAL ZERO MANDAYS GP</td><td>${f.m}</td><td>${d.length.toLocaleString('en-IN')}</td></tr>`;

   const groups=new Set(d.map(r=>r.janpad+'|'+r.engineer+'|'+r.cluster));
   const se=new Set(d.map(r=>r.engineer));
   const gp=new Set(d.map(r=>r.gp));
   const sum=document.getElementById('srdmZeroSummary');
   if(sum)sum.innerHTML=`
     <div class="srdmZeroCard"><small>Zero Mandays GP</small><b>${gp.size.toLocaleString('en-IN')}</b></div>
     <div class="srdmZeroCard"><small>Sub Engineer</small><b>${se.size.toLocaleString('en-IN')}</b></div>
     <div class="srdmZeroCard"><small>Sub Engineer / Cluster</small><b>${groups.size.toLocaleString('en-IN')}</b></div>
     <div class="srdmZeroCard"><small>Month</small><b>${f.m}</b></div>`;

   const meta=document.getElementById('viewMeta');
   if(meta)meta.textContent=`Zero Mandays GP Monitoring | ${f.m} | ${d.length} GP | District: ${f.d==='ALL'?'All':f.d} | Janpad: ${f.j==='ALL'?'All':f.j}`;
 }

 function renderZeroTab(){
   document.body.dataset.reportView='zeromandays';
   const title=document.getElementById('viewTitle');
   if(title)title.textContent='Zero Mandays Generation — GP Monitoring';

   const table=document.getElementById('reportTable');if(!table)return;
   document.getElementById('srdmZeroTools')?.remove();
   document.getElementById('srdmZeroSummary')?.remove();

   table.innerHTML=`<thead><tr>
     <th>SN</th><th>District</th><th>Janpad</th><th>Sub Engineer</th><th>Cluster</th><th>GP Name</th><th>Month</th><th>Mandays</th>
   </tr></thead><tbody></tbody>`;

   const tools=document.createElement('div');tools.id='srdmZeroTools';
   tools.innerHTML=`
     <label>District<select id="zDistrict"><option value="ALL">सभी District</option></select></label>
     <label>Janpad<select id="zJanpad"><option value="ALL">सभी Janpad</option></select></label>
     <label>Sub Engineer<select id="zEngineer"><option value="ALL">सभी Sub Engineer</option></select></label>
     <label>Cluster<select id="zCluster"><option value="ALL">सभी Cluster</option></select></label>
     <label>GP Name<select id="zGP"><option value="ALL">सभी GP</option></select></label>
     <label>Month<select id="zMonth">${MONTHS.map(m=>`<option value="${m}" ${m==='August'?'selected':''}>${m}</option>`).join('')}</select></label>
     <button type="button" id="zReset">Reset</button>`;

   const wrap=table.closest('.table-wrap')||table;
   wrap.insertAdjacentElement('beforebegin',tools);
   const sum=document.createElement('div');sum.id='srdmZeroSummary';tools.insertAdjacentElement('afterend',sum);

   ['zDistrict','zJanpad','zEngineer','zCluster','zGP','zMonth'].forEach(id=>document.getElementById(id).addEventListener('change',()=>{cascade();renderRows()}));
   document.getElementById('zReset').addEventListener('click',()=>{
      ['zDistrict','zJanpad','zEngineer','zCluster','zGP'].forEach(id=>document.getElementById(id).value='ALL');
      document.getElementById('zMonth').value='August';cascade();renderRows();
   });
   cascade();renderRows();
 }

 document.addEventListener('click',e=>{
   const b=e.target.closest('button');
   if(b && b.id!=='srdmZeroBtn' && !b.closest('#srdmZeroTools')){
      setTimeout(()=>{
        if(document.body.dataset.reportView!=='zeromandays'){
          document.getElementById('srdmZeroTools')?.remove();
          document.getElementById('srdmZeroSummary')?.remove();
        }
      },100);
   }
 });
 new MutationObserver(()=>ensureButton()).observe(document.body,{subtree:true,childList:true});
 ensureButton();
})();
